<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { Plus } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import { errorMessage, governanceApi, optionsApi, planningApi } from '@/api'
import type { ConstructionPlan, ID, Organization, ProjectMember, UserAccount } from '@/types/api'
import { formatDateTime } from '@/utils/format'
import PageHeader from '@/components/PageHeader.vue'
import StatusTag from '@/components/StatusTag.vue'
import RemoteState from '@/components/RemoteState.vue'
const rows = ref<ProjectMember[]>([])
const plans = ref<ConstructionPlan[]>([])
const users = ref<UserAccount[]>([])
const orgs = ref<Organization[]>([])
const total = ref(0)
const loading = ref(false)
const error = ref('')
const query = reactive({ page: 1, page_size: 20, plan_id: undefined as ID | undefined, member_role: '' })
const dialog = ref(false)
const saving = ref(false)
const editingId = ref<ID>()
const form = reactive<Partial<ProjectMember>>({ member_role: 'COLLEGE_OWNER', is_primary: 0, effective_from: '' })
async function load() { if (!query.plan_id) { rows.value = []; total.value = 0; return } loading.value = true; error.value = ''; try { const result = await governanceApi.members(query); rows.value = result.items; total.value = result.total } catch (cause) { error.value = errorMessage(cause) } finally { loading.value = false } }
function open(row?: ProjectMember) { editingId.value = row?.id; Object.assign(form, row ? { ...row } : { plan_id: query.plan_id || '', user_id: '', org_id: undefined, member_role: 'COLLEGE_OWNER', is_primary: 0, effective_from: '', effective_to: undefined, handover_from_id: undefined, lock_version: undefined }); dialog.value = true }
async function save() { if (!form.plan_id || !form.user_id || !form.member_role || (!editingId.value && !form.effective_from)) { ElMessage.warning('计划、用户、项目角色和生效时间必填'); return } if (form.member_role === 'COLLEGE_OWNER' && !form.org_id) { ElMessage.warning('学院负责人必须选择项目内学院'); return } saving.value = true; try { if (editingId.value) await governanceApi.updateMember(editingId.value, form); else await governanceApi.createMember(form); ElMessage.success('项目成员与责任任期已保存'); dialog.value = false; await load() } catch (cause) { ElMessage.error(errorMessage(cause)) } finally { saving.value = false } }
onMounted(async () => { try { const [p, u, o] = await Promise.all([planningApi.plans({ page_size: 200 }), optionsApi.users({ page_size: 200 }), optionsApi.organizations({ page_size: 200 })]); plans.value = p.items; users.value = u.items; orgs.value = o.items; if (!query.plan_id && plans.value.length) query.plan_id = plans.value[0].id; await load() } catch (cause) { error.value = errorMessage(cause); ElMessage.error(errorMessage(cause)) } })
</script>
<template>
  <div class="page-container"><PageHeader title="项目成员与负责人" description="每个计划仅 1 名主要校级负责人。负责人交接记录生效时间和交接来源，历史填报、审核仍显示操作发生时的责任人。"><template #actions><el-button type="primary" @click="open()"><el-icon><Plus /></el-icon>添加项目成员</el-button></template></PageHeader>
    <div class="filter-bar"><el-select v-model="query.plan_id" placeholder="全部计划" clearable filterable style="width:320px"><el-option v-for="plan in plans" :key="plan.id" :value="plan.id" :label="plan.plan_name" /></el-select><el-select v-model="query.member_role" placeholder="项目角色" clearable style="width:160px"><el-option label="校级负责人" value="SCHOOL_OWNER" /><el-option label="学院负责人" value="COLLEGE_OWNER" /><el-option label="协同成员" value="COLLABORATOR" /></el-select><el-button type="primary" plain @click="load">查询</el-button></div>
    <RemoteState :loading="loading" :error="error" :empty="!rows.length" @retry="load"><el-table :data="rows"><el-table-column prop="plan_name" label="建设计划" min-width="210"><template #default="{ row }">{{ row.plan_name || plans.find(item => item.id === row.plan_id)?.plan_name }}</template></el-table-column><el-table-column prop="user_name" label="用户" width="120"><template #default="{ row }">{{ row.user_name || users.find(item => item.id === row.user_id)?.user_name }}</template></el-table-column><el-table-column label="项目角色" width="135"><template #default="{ row }"><StatusTag :status="row.member_role" /><el-tag v-if="row.is_primary" size="small" type="danger" style="margin-left:5px">主要负责人</el-tag></template></el-table-column><el-table-column prop="org_name" label="项目内组织" min-width="160"><template #default="{ row }">{{ row.org_name || orgs.find(item => item.id === row.org_id)?.org_name || '—' }}</template></el-table-column><el-table-column label="生效时间" width="165"><template #default="{ row }">{{ formatDateTime(row.effective_from) }}</template></el-table-column><el-table-column label="失效时间" width="165"><template #default="{ row }">{{ formatDateTime(row.effective_to) }}</template></el-table-column><el-table-column label="交接来源" width="110"><template #default="{ row }">{{ row.handover_from_id ? `成员 #${row.handover_from_id}` : '—' }}</template></el-table-column><el-table-column label="操作" width="80"><template #default="{ row }"><el-button link type="primary" @click="open(row)">编辑</el-button></template></el-table-column></el-table><div class="table-footer"><el-pagination v-model:current-page="query.page" v-model:page-size="query.page_size" :total="total" layout="total, sizes, prev, pager, next" @change="load" /></div></RemoteState>
    <el-dialog v-model="dialog" :title="editingId ? '编辑项目成员／负责人交接' : '添加项目成员'" width="650px"><el-form label-width="110px"><el-form-item label="建设计划" required><el-select v-model="form.plan_id" filterable :disabled="Boolean(editingId)" style="width:100%"><el-option v-for="plan in plans" :key="plan.id" :value="plan.id" :label="plan.plan_name" /></el-select></el-form-item><el-form-item label="用户" required><el-select v-model="form.user_id" filterable style="width:100%"><el-option v-for="user in users" :key="user.id" :value="user.id" :label="`${user.user_name}（${user.account_name}）`" /></el-select></el-form-item><div class="form-pair"><el-form-item label="项目角色" required><el-select v-model="form.member_role" style="width:100%"><el-option label="校级负责人" value="SCHOOL_OWNER" /><el-option label="学院负责人" value="COLLEGE_OWNER" /><el-option label="协同成员" value="COLLABORATOR" /></el-select></el-form-item><el-form-item label="项目内组织"><el-select v-model="form.org_id" clearable filterable style="width:100%"><el-option v-for="org in orgs" :key="org.id" :value="org.id" :label="org.org_name" /></el-select></el-form-item></div><el-form-item v-if="form.member_role === 'SCHOOL_OWNER'" label="主要负责人"><el-switch v-model="form.is_primary" :active-value="1" :inactive-value="0" /><span class="form-tip" style="margin-left:10px">每个计划仅 1 名主要校级负责人，后端会校验冲突</span></el-form-item><div class="form-pair"><el-form-item label="生效时间" required><el-date-picker v-model="form.effective_from" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%" /></el-form-item><el-form-item label="失效时间"><el-date-picker v-model="form.effective_to" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%" /></el-form-item></div><el-form-item label="交接来源"><el-select v-model="form.handover_from_id" clearable style="width:100%"><el-option v-for="member in rows.filter(item => item.id !== editingId)" :key="member.id" :value="member.id" :label="`${member.user_name || member.user_id}｜${member.plan_name || member.plan_id}`" /></el-select></el-form-item></el-form><template #footer><el-button @click="dialog = false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog>
  </div>
</template>
<style scoped>.form-pair{display:grid;grid-template-columns:1fr 1fr;gap:12px}</style>
